const RadioOption = ({ id, name, value, label, selectedValue, onChange }) => {
    const isSelected = selectedValue === value;
    return (
        <label className={`radio-option ${isSelected ? 'selected' : ''}`} htmlFor={id}>
            <input
                type="radio"
                id={id}
                name={name}
                value={value}
                checked={isSelected}
                onChange={() => onChange(value)}
            />
            <span className="label-text">{label}</span>
        </label>
    );
};

const NotificationForm = () => {
    const [preference, setPreference] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = (e) => {
        e.preventDefault();
        if (preference) {
            setSubmitted(true);
            console.log('Form submitted with preference:', preference);
        } else {
            alert('Please select a notification preference.');
        }
    };

    return (
        <div className="container">
            <h1>Settings</h1>
            <form onSubmit={handleSubmit}>
                <div className="form-field">
                    <fieldset>
                        <legend>How do you prefer to receive notifications?</legend>
                        <div className="radio-group">
                            <RadioOption
                                id="email"
                                name="notification"
                                value="Email"
                                label="Email"
                                selectedValue={preference}
                                onChange={setPreference}
                            />
                            <RadioOption
                                id="sms"
                                name="notification"
                                value="SMS"
                                label="SMS"
                                selectedValue={preference}
                                onChange={setPreference}
                            />
                            <RadioOption
                                id="push"
                                name="notification"
                                value="Push Notifications"
                                label="Push Notifications"
                                selectedValue={preference}
                                onChange={setPreference}
                            />
                        </div>
                    </fieldset>
                </div>
                <button type="submit">Save Preferences</button>
            </form>
            {submitted && (
                <div className="success-message" role="alert">
                    Your preferences have been saved!
                </div>
            )}
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<NotificationForm />);
